 UNION ALL SELECT 'alfa_z_variacao_pp_'||(v->>'sexo') AS serie,'Versus '||(v->>'ano_base') AS categoria,(v->>'diferenca_pp')::text AS valor,to_jsonb(v->'jovens') AS n,to_jsonb(v->'total') AS d,'Notebook · célula 380 rev1 · congelamento 190 · coleta 05/10/2026' AS fonte,'Diferença em pontos percentuais: (Alfa+Z14+ / todas as participações do gênero no ano) menos a mesma participação no ano base. Inclui desconhecidos e menores14 no denominador; não mede atletas únicos, nem crescimento de quantidade.2025 compara anos completos;2026 compara janeiro–setembro nos dois anos.' AS nota,(v->>'ano_base')::integer AS ordem FROM az CROSS JOIN LATERAL jsonb_array_elements(rows)v WHERE v->>'ano'='2025'),comparacoes AS(SELECT serie,categoria,ordem,jsonb_build_object('serie',serie,'categoria',categoria,'status',CASE WHEN valor IS NULL THEN 'pendente' ELSE 'notebook_em_conciliacao' END,'atual',coalesce((SELECT CASE WHEN jsonb_typeof(c->'atual')='object' THEN c->'atual' END FROM anterior,jsonb_array_elements(p->'comparacoes')c WHERE c->>'serie'=u.serie AND c->>'categoria'=u.categoria),'{}'::jsonb)||jsonb_build_object('valor',valor,'contagem',n,'denominador',d,'populacao',CASE WHEN serie='perfil_cards' THEN (SELECT max((v->>'contas')::bigint) FROM profile,jsonb_array_elements(rows)v WHERE v->>'ano'='2026')::text::jsonb ELSE d END,'numerador',CASE WHEN serie='perfil_cards' THEN (SELECT v->'numerador' FROM profile,jsonb_array_elements(rows)v WHERE v->>'ano'='2026' AND CASE WHEN v->>'regra'='peso_20_300' THEN 'Peso médio' ELSE v->>'categoria' END=u.categoria LIMIT 1) ELSE n END,'base_rotulo','Base própria descrita na nota e SQL congelado','fonte',fonte,'nota',nota)) AS x FROM updates u),
newseries AS(SELECT u.serie,coalesce(max(os.x->>'unidade'),max(un.unidade),CASE WHEN u.serie LIKE 'alfa_z_variacao_pp_%' THEN 'numero' ELSE 'percentual' END) AS unidade,
coalesce(max((os.x->>'casas_decimais')::int),max(un.decimais),CASE WHEN u.serie LIKE 'alfa_z_variacao_pp_%' THEN 2 ELSE 1 END) AS decimais,
jsonb_agg(jsonb_build_object('rotulo',u.categoria,'valor',NULL) ORDER BY u.ordem,u.categoria) AS valores,max(u.nota) AS nota
